# The environment the Vita release defaults set (vita/vgx-game/entry.cpp), plus the choices the console makes by itself: the
# front-end split on, the Vita capabilities, static geometry in main memory.  Source it and pass "$VITA_ENV" as EXTRA_ENV to
# tools/pgo/run_route.sh, so that the renderer runs the same code paths while a profile is recorded as it does on the console.
VITA_ENV="GXV_SPLIT=1 GXV_VITA=1 GXV_STATIC_USAGE=dynamic GXV_SETTINGS=1 GXV_REMAP=1 GXV_BOOTGUARD=1 GXV_DSPNEON=1 GXV_DSPFIR=1 GXV_DSPRAMP=1 GXV_TEVWRAP=2 \
GXV_CLIP_CAPTURE_FIX=1 GXV_ASTRO_DOME_ZOOM_GUARD=1 GXV_DSTALPHA_ZERO=1 GXV_EFB_CREATE_GUARD=1 GXV_RT_ALLOC_GUARD=1 GXV_EFB_REBIND_GUARD=1 \
GXV_DLCACHE_BOUNDS_GUARD=1 GXV_GPU_TIMER_GUARD=1 GXV_SETTINGS_SAVE_GUARD=1 GXV_FIX_INDPREV=1 GXV_FIX_DSTA=1 GXV_FIX_LOGICOP=1 GXV_FIX_TEXOFF=1 \
GXV_NODISCARD=1 GXV_THPHW=1 GXV_VBLANK_PRIO=1 GXV_TAP_CLEAN=1 GXV_SHAKE_LATCH=1 GXV_COPYVAR=1 GXV_AUTOQ_RECOVER=1 GXV_LTMERGE=1 GXV_PALROWS=1 \
GXV_FIX_LODBIAS=1 GXV_AUTHORED_I4_MIPS=1 GXV_SHAKE_PULSE=1 GXV_HDTEX_EYES=1 GXV_FIX_LINES=1 GXV_PAD_DEFAULTS=1 GXV_BOOT_TITLE_FALLBACK=60 \
GXV_AUTOQ_TARGET=30 GXV_AUTOQ_FXSTEP=2 GXV_CHARAA_AUTO=1 GXV_FIX_TEVIN=1 GXV_AUTOQ_RECOVER_SEC=10 GXV_SLIP=1 GXV_SLIP_MAX=20 GXV_RIGIDMERGE=1 \
GXV_CORE0_ALONE=1 GXV_FIXED_DEPTH=1 GXV_PACE_VBLANK_COUNT=1 GXV_AUDIO_THREAD=1 GXV_DRAWDONE_DEFER=1 GXV_CORE3_IO=1"
